import { pop, reveal, greetHubie, celebrate, slideBetMode, setReducedMotion, motionEnabled, watchLive, watchAmbient } from './motion.js?v=house-18';
import { icon, sports, leagues, matches, currencies, crests, games, esportLeagues } from './data.js?v=house-18';

const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const html = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const matchById = id => matches.find(match => match.id === id) || matches[0];
const boostFor = match => match && !match.live ? match.boost : null;
const sampleBet = (id, mid, label, stake, price, status) => ({id, mid, label, stake, price, status, market:'Match result'});
const state = {
  page:'home', mid:'ars', section:'sports', game:'All games', sport:'All sports', competition:'All competitions', timing:'all', query:'', group:'Popular', history:'Open', navCollapsed:false, slipCollapsed:false, navClosed:[], savedMarkets:[], demoMember:false, dayFilter:'all', marketQuery:'', infoMarket:'', pendingCashout:null, favouriteFilter:'All favourites',
  wavePaused:false, balance:1000, fiat:false, currency:'USD', reduceMotion:false, quick:false, quickStake:10, slip:[], follow:[],
  bets:[sampleBet('HB10482','ars','Arsenal',20,1.72,'Open'),sampleBet('HB10481','mad','Real Madrid',10,1.55,'Open'),sampleBet('HB10470','liv','Liverpool',25,1.82,'Won'),sampleBet('HB10462','bar','Draw',10,4.5,'Lost')],
  noLive:false, fail:false, betMode:'single', quickConfigVersion:2, notifications:[], lastQuick:null, lastPlaced:null, quickError:'', panelMessage:'',
};
const storedKeys = ['balance','fiat','currency','quickStake','quickConfigVersion','slip','follow','bets','notifications','lastPlaced','reduceMotion','navCollapsed','slipCollapsed','navClosed','savedMarkets','demoMember'];
try { const saved = JSON.parse(localStorage.getItem('housebets-v3') || '{}'); for (const key of storedKeys) if (saved[key] !== undefined) state[key] = saved[key]; if(saved.quickConfigVersion!==2)state.quickStake=0; } catch {}
state.quickConfigVersion=2;state.betMode='single';if(!Array.isArray(state.notifications))state.notifications=[];
if(state.lastPlaced&&!Array.isArray(state.lastPlaced.bets))state.lastPlaced=null;
for(const key of ['navClosed','savedMarkets'])if(!Array.isArray(state[key]))state[key]=[];
if (!currencies[state.currency]) state.currency = 'USD';
// Existing unplaced selections must explicitly accept the new offered price.
for(const item of state.slip){const boost=boostFor(matches.find(match=>match.id===item.mid));if(boost&&item.market===boost.market&&item.label===boost.label&&item.price!==boost.price){item.oldPrice=item.price;item.price=boost.price;item.changed=true;}}
let saveTimer, searchFrame, noticeTimer, settlementTimer, previousFocus, overlayKind = '';
setReducedMotion(state.reduceMotion);
const desktopPanel=matchMedia('(min-width: 1100px)');
const receiptArt=new Image();receiptArt.decoding='async';receiptArt.fetchPriority='low';
function warmReceiptArt(){if(!receiptArt.src)receiptArt.src='assets/mascot-thumbs-up.png';}
const quickActive=()=>state.betMode==='quick'&&Number.isFinite(state.quickStake)&&state.quickStake>=.01;
function flush() { clearTimeout(saveTimer); try { localStorage.setItem('housebets-v3', JSON.stringify(Object.fromEntries(storedKeys.map(key => [key,state[key]])))); } catch {} }
function save() { clearTimeout(saveTimer); saveTimer = setTimeout(flush,160); }
window.addEventListener('pagehide',flush);
document.addEventListener('visibilitychange',() => { if (document.hidden) flush(); });
const formatters = new Map();
const denomination = () => state.fiat ? state.currency : 'USDT';
const conversion = () => state.fiat ? currencies[state.currency].rate : 1;
function money(value) {
  const code = denomination();
  if (!formatters.has(code)) formatters.set(code,new Intl.NumberFormat('en-US',code === 'USDT' ? {minimumFractionDigits:2,maximumFractionDigits:2} : {style:'currency',currency:code,minimumFractionDigits:2,maximumFractionDigits:2}));
  return formatters.get(code).format((Number(value)||0)*conversion()) + (code === 'USDT' ? ' USDT' : '');
}
const amount = value => `<span data-usdt="${Number(value)||0}">${money(value)}</span>`;
const selectedName = (match,label) => label === '1' ? match.home : label === '2' ? match.away : label === 'X' ? 'Draw' : label;
const symbolFor = sport => sports.find(item => item[0] === sport)?.[1] || 'football';
function badge(match, side=0, large=false){const name=side===0?match.home:match.away,crest=crests[name];return crest?`<img class="team-crest ${large?'team-crest-large':''}" src="assets/crests/${crest}.png" width="${large?54:28}" height="${large?60:30}" alt="${html(name)} crest" decoding="async">`:`<span class="club-badge ${large?'club-badge-large':''}" style="--club:${match.colors[side]}">${html(match.initials[side])}</span>`;}

function leagueMark(name){
 const artwork={
  'Premier League':'<rect width="24" height="18" fill="#f2f5f7"/><path d="M9 0h6v18H9zM0 6h24v6H0z" fill="#d43b4d"/>',
  'LaLiga':'<rect width="24" height="18" fill="#b92c3e"/><path d="M0 4.5h24v9H0z" fill="#efbf3d"/><path d="M6 7h2v4H6z" fill="#b92c3e"/>',
  'Serie A':'<path fill="#17966c" d="M0 0h8v18H0z"/><path fill="#f5f5f1" d="M8 0h8v18H8z"/><path fill="#d6494f" d="M16 0h8v18h-8z"/>',
  'Bundesliga':'<path fill="#101820" d="M0 0h24v6H0z"/><path fill="#ce3946" d="M0 6h24v6H0z"/><path fill="#edbd42" d="M0 12h24v6H0z"/>',
  'Champions League':'<rect width="24" height="18" fill="#184294"/>'+Array.from({length:12},(_,i)=>{const a=i*Math.PI/6;return `<circle cx="${12+5.8*Math.sin(a)}" cy="${9-5.8*Math.cos(a)}" r=".7" fill="#f0ce4d"/>`;}).join('')
 }[name];
 return artwork?`<span class="league-mark" aria-hidden="true"><svg viewBox="0 0 24 18" fill="none">${artwork}</svg></span>`:icon('trophy');
}
const presetNumber=new Intl.NumberFormat('en-US',{useGrouping:false,maximumFractionDigits:2});
function presetLabel(value){return '+'+presetNumber.format(value*conversion());}
function selectionBadge(match,label){
 if(['1',match.home].includes(label))return badge(match);
 if(['2',match.away].includes(label))return badge(match,1);
 return ['X','Draw'].includes(label)?'<span class="draw-mark" aria-hidden="true">X</span>':`<span class="market-mark" aria-hidden="true">${icon('ticket')}</span>`;
}
function notify(message,tone='info'){const target=$('#notice');target.dataset.tone=tone;target.innerHTML=`${icon(tone==='success'?'check':tone==='error'?'close':'info')}<span>${html(message)}</span>`;target.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>target.classList.remove('show'),3000);}
function updateNotifications(){const count=state.notifications.filter(item=>!item.read).length;$$('[data-unread]').forEach(node=>{node.textContent=count;node.hidden=!count;});}
function recordSettlement(bet,announce=true){
 if(state.notifications.some(item=>item.betId===bet.id&&item.status===bet.status))return;
 const note={id:Date.now().toString()+bet.id,betId:bet.id,mid:bet.mid,status:bet.status,payout:bet.payout||0,read:false};state.notifications.unshift(note);state.notifications=state.notifications.slice(0,40);save();updateNotifications();if(announce){pop($('.notifications-button .symbol'));greetHubie($('.hubie-launcher img'));}
 if(!announce)return;
 const match=matchById(bet.mid);$('#settlement-alert').innerHTML=`<button class="settlement-preview" data-notification="${note.id}">${badge(match)}<span><b>Bet settled</b><span>${match.home} v ${match.away}</span><small>${bet.status}${bet.status==='Won'?' &middot; Return '+money(bet.payout):''}</small></span></button><button class="hb-btn hb-btn-ghost hb-btn-square hb-btn-sm icon-btn" data-action="dismiss-settlement" aria-label="Dismiss settlement notification">${icon('close')}</button>`;$('#settlement-alert').classList.add('show');clearTimeout(settlementTimer);settlementTimer=setTimeout(()=>$('#settlement-alert').classList.remove('show'),7000);
}
function notificationsContent(){return `<div class="notification-list">${state.notifications.length?state.notifications.map(note=>{const match=matchById(note.mid);return `<button data-notification="${note.id}" class="notification-item">${badge(match)}<span><b>${note.status==='Cashed out'?'Bet cashed out':'Bet settled'}</b><span>${match.home} v ${match.away}</span><small>${note.status}${note.payout?' &middot; '+money(note.payout):''}</small></span></button>`;}).join(''):empty('You are up to date.','Your settled-bet notifications will appear here.')}</div>`;}

function price(match,label,value,market='Match result',presentation='standard'){
 if(!Number.isFinite(value))return '';
 const boost=boostFor(match)?.market===market&&match.boost.label===label?boostFor(match):null;
 if(boost)value=boost.price;
 const key=`${match.id}|${market}|${label}`,selected=state.slip.some(item=>item.key===key),name=selectedName(match,label),featured=presentation==='featured'&&boost;
 const body=featured?`<span class="boost-selection">${html(name)} to win</span><span class="boost-comparison"><del>${boost.original.toFixed(2)}</del><b>${value.toFixed(2)}</b>${icon('boost')}</span>`:`<span>${html(label)}</span><b>${value.toFixed(2)}${boost?icon('boost','boost-indicator'):''}</b>`;
 return `<button class="price ${selected?'is-picked':''} ${boost?'is-boosted':''} ${featured?'boost-feature':''}" data-pick="${html(key)}" data-mid="${match.id}" data-label="${html(label)}" data-market="${html(market)}" data-price="${value}" aria-pressed="${selected}" aria-label="${html(name)}, ${boost?'boosted from '+boost.original.toFixed(2)+' to ':''}${value.toFixed(2)}">${body}<i class="quick-mark" aria-hidden="true">${icon('bolt')}</i><i class="pick-mark" aria-hidden="true">${icon('check')}</i></button>`;
}
function resultPrices(match) { return match.odds.map((value,i) => match.sport !== 'Football' && i === 1 ? '' : price(match,['1','X','2'][i],value)).join(''); }
function status(match) { return match.live ? `<span class="in-play"><i></i>LIVE</span><time>${html(match.clock)}</time>` : `<span>${match.day||'Today'}</span><time>${match.clock}</time>`; }
function followButton(name, text = false) { const following = state.follow.includes(name); return `<button class="${text?'follow-label':'icon-btn'} ${following?'is-followed':''}" data-follow="${html(name)}" aria-label="${following?'Unfollow':'Follow'} ${html(name)}" aria-pressed="${following}">${icon('star')}${text?`<span>${following?'Following':'Follow'} ${html(name)}</span>`:''}</button>`; }
function fixture(match) {
  return `<article class="fixture" data-event="${match.id}"><div class="fixture-meta">${match.game?gameMark(match.game):icon(symbolFor(match.sport))}<span>${match.game?match.game+' · ':''}${html(match.league)}</span>${followButton(match.league)}</div><div class="fixture-body"><div class="fixture-time">${status(match)}</div><a class="fixture-pair" href="#match/${match.id}"><span class="fixture-team">${badge(match)}<span>${html(match.home)}</span><b>${match.live?match.score[0]:''}</b></span><span class="fixture-team">${badge(match,1)}<span>${html(match.away)}</span><b>${match.live?match.score[1]:''}</b></span></a><div class="price-group ${match.sport!=='Football'?'two-prices':''}">${resultPrices(match)}</div></div></article>`;
}
function empty(title,copy,action='') { return `<div class="zero-state"><img src="assets/mascot.jpg" width="90" height="90" alt="Housebets sloth mascot"><h2>${title}</h2><p>${copy}</p>${action}</div>`; }
function matching() {
  return matches.filter(match => inSection(match) && (state.game==='All games'||match.game===state.game) && (state.sport==='All sports'||match.sport===state.sport) && (state.competition==='All competitions'||match.league===state.competition) && (state.timing==='all'||(state.timing==='live'?match.live:!match.live)) && (state.dayFilter==='all'||(state.dayFilter==='tomorrow'?(match.day==='Tomorrow'):match.day!=='Tomorrow')) && (!state.noLive||!match.live) && (!state.query||`${match.home} ${match.away} ${match.league} ${match.sport} ${match.game||''} match result goals`.toLowerCase().includes(state.query.toLowerCase())));
}
const inSection=match=>(match.sport==='Esports')===(state.section==='esports');
function groupedFixtures(events){
 const groups=new Map();for(const match of events){const key=match.league;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(match);}
 return [...groups].map(([league,events])=>`<section class="competition-section hb-card" aria-label="${html(league)}"><div class="competition-header">${events[0].game?gameMark(events[0].game):leagueMark(league)}<h3>${html(league)}</h3>${followButton(league)}<span class="competition-count">${events.length} ${events.length===1?'event':'events'}</span><span class="competition-market-name">Match ${events[0].sport==='Football'?'result':'winner'}</span></div><div class="competition-fixtures">${events.map(fixture).join('')}</div></section>`).join('');
}
function fixtureResults() {
  if(state.page==='following')return followingResults();
  const events = matching();
  if (events.length) return groupedFixtures(events);
  if (state.page==='live' && state.timing==='live') return empty('A quiet moment.','Nothing live right now. See what is starting soon.')+`<h3 class="list-subtitle">Starting soon</h3>`+matches.filter(match => inSection(match) && !match.live && (state.dayFilter==='all'||(state.dayFilter==='tomorrow'?match.day==='Tomorrow':match.day!=='Tomorrow')) && (state.game==='All games'||match.game===state.game) && (state.sport==='All sports'||match.sport===state.sport) && (state.competition==='All competitions'||match.league===state.competition) && (!state.query||`${match.home} ${match.away} ${match.league}`.toLowerCase().includes(state.query.toLowerCase()))).map(fixture).join('');
  return empty('No matches found.','Try another sport or competition.',`<button class="hb-btn hb-btn-soft" data-action="reset">Reset filters</button>`);
}
function search() { return `<label class="finder hb-input hb-input-sm">${icon('search')}<input id="finder" type="search" autocomplete="off" placeholder="Search teams or competitions" aria-label="Search teams, players, competitions and markets" value="${html(state.query)}"></label>`; }
function daySelect(){return `<label class="select-control day-control"><span class="sr-only">Filter match day</span><select class="hb-select hb-select-sm" id="match-day">${[['all','All dates'],['today','Today'],['tomorrow','Tomorrow']].map(([value,label])=>`<option value="${value}" ${state.dayFilter===value?'selected':''}>${label}</option>`).join('')}</select></label>`;}
function competitionSelect() { return `<label class="select-control"><span class="sr-only">Filter competition</span><select class="hb-select hb-select-sm" id="competition"><option>All competitions</option>${(state.section==='esports'?esportLeagues:[...leagues,'Coastal Open','City League']).map(name => `<option ${state.competition===name?'selected':''}>${html(name)}</option>`).join('')}</select></label>`; }
function timingTabs() { return `<nav class="line-tabs" aria-label="Event timing">${[['all','All'],['live','Live now'],['soon','Starting soon']].map(([value,label]) => `<button data-timing="${value}" class="${state.timing===value?'on':''}" aria-pressed="${state.timing===value}">${value==='live'?'<i class="live-dot"></i>':''}${label}</button>`).join('')}</nav>`; }
function gameMark(game){return `<span class="game-mark game-${game.replaceAll(' ','').toLowerCase()}" aria-hidden="true">${game==='Valorant'?'<svg viewBox="0 0 24 24"><path d="M2 4v10l7 7h7L2 4Zm20 0-9 11h9V4Z"/></svg>':game==='Dota 2'?'<svg viewBox="0 0 24 24"><path d="M2 2h20v20H2z"/><path class="game-cut" d="m5 5 14 14M15 5l4 1v4M5 14v4l4 1"/></svg>':game==='LoL'?'L':'CS'}</span>`;}
function sportsNav() { return state.section==='esports'?`<nav class="sports-nav" aria-label="Esports games">${['All games',...games].map(name=>`<button data-game="${name}" class="${state.game===name?'on':''}" aria-pressed="${state.game===name}">${name==='All games'?icon('esports'):gameMark(name)}${name}</button>`).join('')}</nav>`:`<nav class="sports-nav" aria-label="Sports">${sports.filter(([name])=>name!=='Esports').map(([name,symbol])=>`<button data-sport="${name}" class="${state.sport===name?'on':''}" aria-pressed="${state.sport===name}">${icon(symbol)}${name}</button>`).join('')}</nav>`; }
function title(name,copy,extra='') { return `<div class="page-title"><div><h1>${name}</h1>${copy?`<p>${copy}</p>`:''}</div>${extra}</div>`; }
function arena(match) {
  return `<article class="arena hb-card hb-carousel-item" data-event="${match.id}"><div class="arena-top"><span>${match.game?gameMark(match.game):icon(symbolFor(match.sport))}${html(match.league)}</span><span class="arena-live">${status(match)}</span></div><a class="arena-duel" href="#match/${match.id}" aria-label="${html(match.home)} v ${html(match.away)} markets"><div>${badge(match,0,true)}<strong>${html(match.home)}</strong></div><div class="arena-score"><b>${match.live?`${match.score[0]}<span>:</span>${match.score[1]}`:'vs'}</b><small>${match.live?'In play':'Kick-off'}</small></div><div>${badge(match,1,true)}<strong>${html(match.away)}</strong></div></a><div class="price-group ${match.sport!=='Football'?'two-prices':''}" aria-label="Match ${match.sport==='Football'?'result':'winner'}">${resultPrices(match)}</div></article>`;
}
function highlightedMatches(events){return `<section class="highlights" aria-labelledby="highlights-title"><div class="highlights-heading"><h2 id="highlights-title">Highlighted matches</h2><div class="carousel-controls"><button class="hb-btn hb-btn-ghost hb-btn-square hb-btn-sm" data-carousel="-1" aria-label="Previous highlighted matches" aria-controls="highlighted-matches" disabled>${icon('chevron')}</button><button class="hb-btn hb-btn-ghost hb-btn-square hb-btn-sm" data-carousel="1" aria-label="Next highlighted matches" aria-controls="highlighted-matches">${icon('chevron')}</button></div></div><div id="highlighted-matches" class="hb-carousel hb-carousel-start" tabindex="0" role="region" aria-labelledby="highlights-title">${events.map(arena).join('')}</div></section>`;}
function updateCarousel(){const track=$('#highlighted-matches');if(!track)return;const max=track.scrollWidth-track.clientWidth;$$('[data-carousel]').forEach(button=>button.disabled=Number(button.dataset.carousel)<0?track.scrollLeft<2:track.scrollLeft>=max-2);}
function moveCarousel(direction){const track=$('#highlighted-matches');if(!track)return;const step=track.firstElementChild.getBoundingClientRect().width+12;track.scrollBy({left:step*direction,behavior:motionEnabled()?'smooth':'instant'});}
function setupCarousel(){const track=$('#highlighted-matches');if(!track)return;let frame;track.addEventListener('scroll',()=>{if(frame)return;frame=requestAnimationFrame(()=>{frame=null;updateCarousel();});},{passive:true});requestAnimationFrame(updateCarousel);}
window.addEventListener('resize',updateCarousel,{passive:true});
function home() {
 const candidates=matches.filter(match=>inSection(match)&&(state.game==='All games'||match.game===state.game)&&(state.sport==='All sports'||match.sport===state.sport)&&(state.competition==='All competitions'||match.league===state.competition)&&(!state.noLive||!match.live));
 const featured=[...candidates.filter(match=>match.live),...candidates.filter(match=>!match.live)].slice(0,8),liveCount=candidates.filter(match=>match.live).length,upcoming=candidates.length-liveCount;
 return `${title(state.section==='esports'?'Esports':state.sport==='All sports'?'Sportsbook':state.sport,`<span class="title-event-counts"><span><i class="live-dot"></i>${liveCount} live</span><span>${upcoming} upcoming</span></span>`,search())}${featured.length?matchSpotlight(featured.find(match=>boostFor(match))||featured[0])+highlightedMatches(featured):''}<section class="matches-section"><div class="section-title"><h2>Matches</h2><a href="${sectionLink('live')}">View live events</a></div>${sportsNav()}<div class="results-controls">${timingTabs()}<div class="results-filters">${daySelect()}${competitionSelect()}</div></div><div id="fixtures">${fixtureResults()}</div></section>`;
}
function live() {
 const count=state.noLive?0:matches.filter(match=>inSection(match)&&match.live).length;
 return `${title(state.section==='esports'?'Live esports':'Live sports',`${count} events in play`,search())}${sportsNav()}<section class="live-layout"><div class="results-controls">${timingTabs()}<div class="results-filters">${daySelect()}${competitionSelect()}</div></div><div id="fixtures">${fixtureResults()}</div><details class="prototype-controls"><summary>Prototype scenarios</summary><button data-action="nothing-live">${state.noLive?'Restore live events':'Show nothing live'}</button></details></section>`;
}
function competitionLinks(events = matches.filter(match=>match.sport==='Football')) {
  return ['All competitions',...new Set(events.map(match=>match.league))].map((name,i)=>`<button class="competition-link ${state.competition===name?'on':''}" data-competition="${html(name)}" aria-pressed="${state.competition===name}"><span class="league-mark">${i===0?'ALL':name.split(' ').map(word=>word[0]).join('').slice(0,3)}</span><span>${html(name)}</span><small>${events.filter(match=>name==='All competitions'||match.league===name).length}</small></button>`).join('');
}
function football() {
 return `${title('Football','Premier League and European competitions.',search())}<nav class="league-tabs" aria-label="Football competitions">${['All competitions',...leagues].map(name=>`<button data-competition="${name}" class="${state.competition===name?'on':''}" aria-pressed="${state.competition===name}">${name==='All competitions'?'':leagueMark(name)}${name==='All competitions'?'All leagues':name}</button>`).join('')}</nav><section class="football-layout"><div class="results-controls">${timingTabs()}<div class="results-filters">${daySelect()}${competitionSelect()}</div></div><div id="fixtures">${fixtureResults()}</div></section>`;
}
const matchesFavourite=(match,name)=>[match.home,match.away,match.league,match.sport,match.game].includes(name);
function favouriteMark(name){const match=matches.find(match=>match.home===name||match.away===name);return match?badge(match,match.away===name?1:0).replace(/alt="[^"]*"/,'alt=""'):icon('trophy');}
function followSuggestions(){return `<div class="follow-suggestions">${['Arsenal','Premier League','Champions League','CS2'].filter(name=>!state.follow.includes(name)).map(name=>`<button data-follow="${html(name)}" aria-pressed="false" aria-label="Follow ${html(name)}">${favouriteMark(name)}<span>${html(name)}</span>${icon('plus')}</button>`).join('')}</div>`;}
function followingResults(){
 const events=matches.filter(match=>state.follow.some(name=>matchesFavourite(match,name))&&(state.favouriteFilter==='All favourites'||matchesFavourite(match,state.favouriteFilter))&&(!state.noLive||!match.live)&&(!state.query||`${match.home} ${match.away} ${match.league} ${match.sport} ${match.game||''}`.toLowerCase().includes(state.query.toLowerCase())));
 if(!events.length)return `<div class="following-quiet"><h2>No matches to show</h2><p>${state.query?'Try another search.':'Matches from your favourites will appear here when they are scheduled.'}</p></div>`;
 return [['live','Live now'],['soon','Upcoming']].filter(([type])=>state.timing==='all'||state.timing===type).map(([type,label])=>{const list=events.filter(match=>type==='live'?match.live:!match.live);return `<section class="following-group" aria-label="${label}"><div class="following-group-title"><h2>${type==='live'?'<i class="live-dot"></i>':''}${label}</h2><span>${list.length} ${list.length===1?'match':'matches'}</span></div>${list.length?groupedFixtures(list):`<p class="following-quiet-row">${type==='live'?'None of your favourites are playing right now.':'No upcoming matches for these favourites yet.'}</p>`}</section>`;}).join('');
}
function following(){
 const saved=state.follow.length;
 return `${title('Following','Your teams and competitions, in one place.',search())}${saved?`<section class="favourites-bar" aria-label="Your favourites"><div class="favourite-chips"><button class="favourite-all ${state.favouriteFilter==='All favourites'?'active':''}" data-favourite-filter="All favourites" aria-pressed="${state.favouriteFilter==='All favourites'}">All favourites <span>${saved}</span></button>${state.follow.map(name=>`<div class="favourite-chip ${state.favouriteFilter===name?'active':''}"><button data-favourite-filter="${html(name)}" aria-pressed="${state.favouriteFilter===name}">${favouriteMark(name)}<span>${html(name)}</span></button><button data-unfollow="${html(name)}" aria-label="Unfollow ${html(name)}">${icon('close')}</button></div>`).join('')}</div><details class="find-favourites"><summary>Find more to follow</summary>${followSuggestions()}<a href="#football">Browse football competitions</a><a href="#home?section=esports">Browse esports</a></details></section><div class="results-controls following-controls">${timingTabs()}</div><div id="fixtures">${followingResults()}</div>`:`<section class="following-onboarding"><img src="assets/mascot.jpg" width="88" height="88" alt="Hubie the Housebets sloth"><h2>Make this your home ground.</h2><p>Follow teams and competitions to keep their live and upcoming matches here.</p>${followSuggestions()}<a class="hb-btn hb-btn-soft" href="#football">Browse football</a></section>`}`;
}
const groups = ['Popular','Goals','Halves','Handicaps','Goalscorers','Corners & cards'];
function marketData(match,group=state.group) {
  if (match.sport!=='Football') {
    if (group==='Handicaps') return [['Handicap',[`${match.home} ${match.game?'-1.5':'-2.5'}`,`${match.away} ${match.game?'+1.5':'+2.5'}`],[1.91,1.89]]];
    if (group==='Goals') return [[match.game?'Total maps · 2.5':match.sport==='Tennis'?'Total games · 22.5':'Total points · 179.5',['Over','Under'],[1.92,1.88]]];
    return [['Match winner',[match.home,match.away],[match.odds[0],match.odds[2]]]];
  }
  return {
    Popular:[['Match result',['1','X','2'],match.odds],['Total goals · 3.5',['Over 3.5','Under 3.5'],[1.88,1.92]],['Goal in the next 10 minutes',['Yes','No'],[2.80,1.42]]],
    Goals:[['Total goals · 3.5',['Over 3.5','Under 3.5'],[1.88,1.92]],['Next goal',[match.home,'No goal',match.away],[1.70,4.20,3.80]]],
    Halves:[['Second-half result',['1','X','2'],[1.95,2.80,4.10]]],
    Handicaps:[['Asian handicap',[`${match.home} -1.5`,`${match.away} +1.5`],[2.10,1.76]]],
    Goalscorers:[['Next goalscorer · fictional players',['A. North','J. Vale'],[3.40,4.80]]],
    'Corners & cards':[['Total corners · 9.5',['Over 9.5','Under 9.5'],[1.90,1.90]],['Total cards · 3.5',['Over 3.5','Under 3.5'],[1.88,1.92]]],
  }[group] || [];
}
function allMatchMarkets(match){const names=match.sport==='Football'?groups:['Popular','Goals','Handicaps'],markets=new Map();for(const group of names)for(const entry of marketData(match,group))if(!markets.has(entry[0]))markets.set(entry[0],entry);return [...markets.values()];}
function marketRows(){
 const match=matchById(state.mid),query=state.marketQuery.trim().toLowerCase();
 let markets=query||state.group==='Saved'?allMatchMarkets(match):marketData(match);
 if(state.group==='Saved')markets=markets.filter(([name])=>state.savedMarkets.includes(match.sport+'|'+name));
 if(query)markets=markets.filter(([name,labels])=>(name+' '+labels.join(' ')).toLowerCase().includes(query));
 if(!markets.length)return `<div class="market-empty">${icon(state.group==='Saved'?'star':'search')}<h2>${state.group==='Saved'?'Your go-to markets, right here.':'No markets found.'}</h2><p>${state.group==='Saved'?'Save a market with its star to find it quickly on future matches.':'Try a team name or a market such as goals, corners or match result.'}</p><button class="hb-btn hb-btn-soft" data-action="reset-markets">Browse popular markets</button></div>`;
 return `${query?`<p class="market-result-count" role="status">${markets.length} ${markets.length===1?'market':'markets'} found</p>`:''}${markets.map(([name,labels,values])=>{const key=match.sport+'|'+name,saved=state.savedMarkets.includes(key);return `<section class="market-row market-card hb-card"><div class="market-card-heading"><h2>${html(name)}</h2><button class="icon-btn market-info" data-market-info="${html(name)}" aria-label="About ${html(name)}">${icon('info')}</button><button class="icon-btn ${saved?'is-followed':''}" data-save-market="${html(key)}" aria-label="${saved?'Unsave':'Save'} ${html(name)}" aria-pressed="${saved}">${icon('star')}</button></div><div class="price-group ${labels.length===2?'two-prices':''}">${labels.map((label,i)=>price(match,label,values[i],name).replace('<span>'+html(label)+'</span>','<span>'+html(selectedName(match,label))+'</span>')).join('')}</div></section>`;}).join('')}`;
}
function drawMarkets(animate=true){const root=$('#markets');if(!root)return;root.innerHTML=marketRows();const match=matchById(state.mid),count=allMatchMarkets(match).filter(([name])=>state.savedMarkets.includes(match.sport+'|'+name)).length;$$('[data-saved-market-count]').forEach(node=>node.textContent=count);syncQuickState();if(animate)reveal($('.market-row',root)||root.firstElementChild);}
function artFor(match){return match.sport==='Football'?'assets/stadium-night.webp':match.sport==='Esports'?'assets/esports-arena.webp':'';}
function matchSpotlight(match){
 const art=artFor(match),boost=boostFor(match),quote=boost?`${match.home} to win at ${boost.price.toFixed(2)}. That’s a House boost!`:'Big stage. Great teams. Enjoy this one.';
 return `<article class="match-spotlight hb-card ${boost?'boosted-spotlight':''}">${art?`<img class="spotlight-art" src="${art}" width="1200" height="675" alt="" fetchpriority="high">`:''}<div class="spotlight-shade"></div><div class="spotlight-copy"><span class="spotlight-label">${icon(boost?'boost':'trophy')}${boost?'HUBIE’S ODDS BOOST':'HUBIE’S MATCHDAY PICK'}</span><h2>${html(match.home)} <span>v</span> ${html(match.away)}</h2><p>${html(match.league)}<span>${match.live?'Live now':(match.day||'Today')+' · '+match.clock}</span></p>${boost?price(match,boost.label,boost.price,boost.market,'featured'):''}<a class="spotlight-link" href="#match/${match.id}">Explore match</a></div><div class="spotlight-host"><blockquote class="hubie-speech" aria-label="Hubie says"><q data-hubie-quote>${html(quote)}</q></blockquote><button class="spotlight-hubie" data-action="hubie-pick" aria-label="Say hello to Hubie" title="Say hello to Hubie"><img src="assets/hubie-pointing.webp" width="220" height="260" alt="Hubie pointing toward the featured match"></button></div></article>`;
}
function matchPage(){
 const match=matchById(state.mid),available=match.sport==='Football'?groups:['Popular','Goals','Handicaps'],art=artFor(match),savedCount=allMatchMarkets(match).filter(([name])=>state.savedMarkets.includes(match.sport+'|'+name)).length;
 const phase=match.live?(match.sport==='Football'?(parseInt(match.clock)<45?'First half':'Second half'):match.game?'Best of three':'In play'):'Kick-off';
 return `<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="${sectionLink()}">${state.section==='esports'?'Esports':'Sports'}</a><a href="${match.game?sectionLink('home',{game:match.game}):match.sport==='Football'?'#football':sectionLink('home',{sport:match.sport})}">${match.game||match.sport}</a><span>${html(match.league)}</span></nav><h1 class="sr-only">${html(match.home)} v ${html(match.away)}</h1><section class="event-hero" aria-label="Match scoreboard">${art?`<img class="event-hero-art" src="${art}" width="1200" height="675" alt="" fetchpriority="high">`:''}<div class="event-hero-shade"></div><div class="event-hero-top"><span>${match.game?gameMark(match.game):leagueMark(match.league)}${html(match.league)}</span><div>${followButton(match.league)}<button class="icon-btn" data-action="share-match" aria-label="Copy match link" title="Copy match link">${icon('link')}</button></div></div><div class="event-scoreboard"><div class="event-team"><span class="event-crest">${badge(match,0,true)}</span><h2>${html(match.home)}</h2>${followButton(match.home)}</div><div class="event-score"><span class="event-phase">${phase}</span><b>${match.live?`${match.score[0]}<span>:</span>${match.score[1]}`:'VS'}</b><div class="event-clock ${match.clock.length>7?'clock-extended':''}">${status(match)}</div></div><div class="event-team"><span class="event-crest">${badge(match,1,true)}</span><h2>${html(match.away)}</h2>${followButton(match.away)}</div></div><div class="event-hero-bottom"><span>${match.sport==='Football'?'Full time · 90 minutes':match.game?match.game:match.sport}</span><span>${match.live?'In play':match.day||'Today'}</span></div></section><section class="event-main-market" aria-label="Main match market"><div><h2>Match ${match.sport==='Football'?'result':'winner'}</h2><span>${match.live?'Current match odds':'Pre-match odds'}</span></div><div class="price-group ${match.sport!=='Football'?'two-prices':''}">${match.odds.map((value,i)=>Number.isFinite(value)?price(match,['1','X','2'][i],value).replace('<span>'+['1','X','2'][i]+'</span>','<span>'+html(selectedName(match,['1','X','2'][i]))+'</span>'):'').join('')}</div></section><section class="event-markets" aria-label="Betting markets"><div class="market-toolbar"><h2>Match markets</h2><label class="market-search hb-input">${icon('search')}<input id="market-search" type="search" placeholder="Search markets" aria-label="Search this match's markets" value="${html(state.marketQuery)}"></label></div><div class="market-layout"><nav class="market-navigation" aria-label="Market groups">${[...available,'Saved'].map(group=>`<button class="${state.group===group?'on':''}" data-group="${group}" aria-pressed="${state.group===group}">${group==='Saved'?icon('star'):''}${group==='Goals'&&match.sport!=='Football'?'Totals':group}${group==='Saved'?`<small class="count-badge hb-badge hb-badge-sm" data-saved-market-count>${savedCount}</small>`:''}</button>`).join('')}</nav><div id="markets">${marketRows()}</div></div></section><section class="more-events"><h2>More ${match.game||match.sport.toLowerCase()}</h2><div class="related-grid">${matches.filter(other=>other.sport===match.sport&&other.id!==match.id).slice(0,3).map(other=>`<a class="related-match" href="#match/${other.id}"><span class="related-crest-pair">${badge(other)}${badge(other,1)}</span><span><b>${html(other.home)} v ${html(other.away)}</b><small>${other.live?'Live · '+other.clock:(other.day||'Today')+' · '+other.clock}</small></span></a>`).join('')}</div></section><p class="small-print">${icon('info')} Scores, clocks and odds are sample data.</p>`;
}
function cashoutReview(){
 const quote=state.pendingCashout,bet=quote&&state.bets.find(item=>item.id===quote.id&&item.status==='Open');
 if(!bet)return `<div class="cashout-review"><p>This bet is no longer available to cash out.</p><button class="hb-btn hb-btn-soft" data-action="close">Close</button></div>`;
 const match=matchById(bet.mid);
 return `<section class="cashout-review" aria-label="Review cash out"><div class="cashout-selection">${selectionBadge(match,bet.label)}<div><h3>${html(bet.label)}</h3><p>${html(bet.market)}</p></div><b>${bet.price.toFixed(2)}</b></div><p class="cashout-match">${html(match.home)} v ${html(match.away)}</p><dl class="cashout-values"><div><dt>Original stake</dt><dd>${money(bet.stake)}</dd></div><div><dt>Potential return</dt><dd>${money(bet.stake*bet.price)}</dd></div></dl><div class="cashout-offer"><span>You will receive</span><strong>${money(quote.offer)}</strong></div><p id="cashout-explanation" class="cashout-explanation">Confirming cash out settles this bet immediately at the amount shown.</p><div class="cashout-actions"><button class="hb-btn hb-btn-soft" data-action="cancel-cashout">Keep bet open</button><button class="hb-btn hb-btn-primary" data-action="confirm-cashout" aria-describedby="cashout-explanation">Confirm cash out</button></div></section>`;
}
function confirmCashout(){
 const quote=state.pendingCashout,bet=quote&&state.bets.find(item=>item.id===quote.id&&item.status==='Open');
 if(!bet||quote.offer!==+(bet.stake*.85).toFixed(2)){state.pendingCashout=null;closeOverlay();notify('Cash out is no longer available. Your bet was not changed.','error');return;}
 state.pendingCashout=null;bet.status='Cashed out';bet.payout=quote.offer;state.balance=+(state.balance+bet.payout).toFixed(2);recordSettlement(bet,false);save();closeOverlay();drawPage();notify('Bet cashed out','success');requestAnimationFrame(()=>($('.activity>summary')||$('#page'))?.focus({preventScroll:true}));
}
function betHistory() {
  const bets=state.bets.filter(bet=>state.history==='All'||(state.history==='Open'?bet.status==='Open':bet.status!=='Open'));
  if (!bets.length) return empty(`No ${state.history.toLowerCase()} bets yet.`,'Your singles appear here after they are placed.',`<a class="hb-btn hb-btn-soft" href="#home">Explore matches </a>`);
  return bets.map(bet=>{
    const match=matchById(bet.mid), open=bet.status==='Open', payout=open?bet.stake*bet.price:bet.payout??(bet.status==='Won'?bet.stake*bet.price:0);
    return `<details class="activity hb-card" data-bet-id="${bet.id}" ${open?'open':''}><summary><span class="activity-heading">${selectionBadge(match,bet.label)}<b>${match.home} <small>v</small> ${match.away}</b><span>${html(bet.label)} · ${html(bet.market)}</span></span><span class="hb-badge hb-badge-soft hb-badge-sm bet-state ${bet.status.toLowerCase().replaceAll(' ','-')}">${bet.status}</span><span class="activity-return">${amount(payout)}</span><span class="details-mark" aria-hidden="true">+</span></summary><div class="activity-content"><div class="activity-reference">${bet.id} <span>${match.league}</span></div><div class="activity-values"><dl><dt>Stake</dt><dd>${amount(bet.stake)}</dd></dl><dl><dt>Odds</dt><dd>${bet.price.toFixed(2)}</dd></dl><dl><dt>${open?'Potential return':'Return'}</dt><dd class="cyan">${amount(payout)}</dd></dl>${open?`<button class="hb-btn hb-btn-soft cashout" data-cashout="${bet.id}">Cash out ${amount(bet.stake*.85)}</button>`:`<span class="settlement">${icon(bet.status==='Lost'?'close':'check')}${bet.status==='Cashed out'?'Cashed out':'Settled'}</span>`}</div></div></details>`;
  }).join('');
}
function myBets() {
  return `${title('My bets','Your open and settled bets.',`<button class="hb-btn hb-btn-soft" data-action="slip">Open bet slip </button>`)}<div class="history-overview"><span>Open stake <b>${amount(state.bets.filter(bet=>bet.status==='Open').reduce((sum,bet)=>sum+bet.stake,0))}</b></span><span>Potential returns <b class="cyan">${amount(state.bets.filter(bet=>bet.status==='Open').reduce((sum,bet)=>sum+bet.stake*bet.price,0))}</b></span></div><div class="history-toolbar"><nav class="line-tabs" aria-label="Bet history">${['Open','Settled','All'].map(name=>`<button data-history="${name}" class="${state.history===name?'on':''}" aria-pressed="${state.history===name}"><span class="tab-label">${name}</span><small class="count-badge hb-badge hb-badge-sm">${state.bets.filter(bet=>name==='All'||(name==='Open'?bet.status==='Open':bet.status!=='Open')).length}</small></button>`).join('')}</nav></div><section class="activity-stream"><div id="history">${betHistory()}</div></section><details class="prototype-controls"><summary>Prototype scenarios</summary><button data-action="settle">Settle next open bet as won</button></details>`;
}
function sectionLink(page='home',extra={}){const params=new URLSearchParams({... (state.section==='esports'?{section:'esports'}:{}),...extra});return '#'+page+(params.size?'?'+params:'');}
function sidebarContent(drawer=false){
 const esports=state.section==='esports',competitions=esports?esportLeagues:leagues,liveCount=state.noLive?0:matches.filter(match=>inSection(match)&&match.live).length;
 const navItem=(page,symbol,label,count='')=>`<a class="sidebar-item ${page==='following'?'sidebar-following ':''}${state.page===page?'selected':''}" href="${sectionLink(page)}" aria-label="${label}" title="${label}" ${state.page===page?'aria-current="page"':''}>${icon(symbol)}<span class="nav-label">${label}</span>${count}</a>`;
 const group=(key,label,symbol,content)=>`<details class="nav-group hb-collapse" data-nav-group="${key}" ${state.navClosed.includes(key)?'':'open'}><summary class="hb-collapse-title" title="${label}">${icon(symbol)}<span class="nav-label">${label}</span><span class="nav-expander" aria-hidden="true"></span></summary><div class="hb-collapse-content"><nav aria-label="${label}">${content}</nav></div></details>`;
 const championshipLinks=competitions.map((name,i)=>`<a href="${sectionLink(esports?'home':'football',{competition:name})}" class="sidebar-item ${state.competition===name?'selected':''}" aria-label="${html(name)}" title="${html(name)}">${esports?gameMark(games[i]):leagueMark(name)}<span class="nav-label">${html(name)}</span></a>`).join('');
 const sportLinks=esports?games.map(name=>`<a class="sidebar-item ${state.game===name?'selected':''}" href="${sectionLink('home',{game:name})}" aria-label="${name}" title="${name}">${gameMark(name)}<span class="nav-label">${name==='LoL'?'League of Legends':name==='CS2'?'Counter-Strike 2':name}</span><small>${matches.filter(match=>match.game===name).length}</small></a>`).join(''):sports.filter(([name])=>!['All sports','Esports'].includes(name)).map(([name,symbol])=>`<a class="sidebar-item ${state.sport===name?'selected':''}" href="${name==='Football'?'#football':sectionLink('home',{sport:name})}" aria-label="${name}" title="${name}">${icon(symbol)}<span class="nav-label">${name}</span><small>${matches.filter(match=>match.sport===name).length}</small></a>`).join('');
 return `${drawer?`<div class="sidebar-brand"><a class="brand" href="#home" aria-label="Housebets"><img src="assets/house-avatar.jpg" alt="" width="28" height="28"><span>Housebets</span></a><button class="hb-btn hb-btn-ghost hb-btn-square hb-btn-sm icon-btn" data-action="close" aria-label="Close menu">${icon('close')}</button></div>`:''}<div class="sidebar-top"><span class="sidebar-caption">YOUR SPORTSBOOK</span><nav class="section-switch" aria-label="Sports or Esports"><a href="#home" class="${esports?'':'active'}" aria-label="Sports" title="Sports" ${esports?'':'aria-current="true"'}>${icon('football')}<span class="nav-label">Sports</span></a><a href="#home?section=esports" class="${esports?'active':''}" aria-label="Esports" title="Esports" ${esports?'aria-current="true"':''}>${icon('esports')}<span class="nav-label">Esports</span></a></nav></div><div class="sidebar-scroll"><nav class="sidebar-main" aria-label="Main navigation">${navItem('home','home','Home')}${navItem('live','live','Live',`<small class="count-badge hb-badge hb-badge-sm nav-live-count">${liveCount}</small>`)}${navItem('following','star','Following',`<small class="count-badge hb-badge hb-badge-sm" data-follow-count>${state.follow.length}</small>`)}${navItem('bets','ticket','My bets',`<small class="count-badge hb-badge hb-badge-sm" data-open-bets>${state.bets.filter(bet=>bet.status==='Open').length}</small>`)}</nav>${group('championships','Top competitions','trophy',championshipLinks)}${group('sports',esports?'Esports':'Sports','grid',sportLinks)}<div class="sidebar-personal"><button class="sidebar-item notifications-button" data-action="notifications" title="Notifications" aria-label="Notifications">${icon('bell')}<span class="nav-label">Notifications</span><b class="count-badge hb-badge hb-badge-sm" data-unread hidden></b></button><button class="sidebar-item" data-action="help" title="How betting works" aria-label="How betting works">${icon('info')}<span class="nav-label">How betting works</span></button></div></div><div class="sidebar-account"><button class="hubie-launcher" data-action="hubie" aria-label="Meet Hubie" title="Meet Hubie"><img src="assets/mascot.jpg" width="38" height="38" alt=""><span>Hubie</span></button><span class="sidebar-host-copy"><b>Hubie’s corner</b><small>Your House host</small></span><button class="hb-btn hb-btn-ghost hb-btn-square hb-btn-sm icon-btn" data-action="settings" aria-label="Display settings" title="Display settings">${icon('settings')}</button></div>`;
}
function headerContent(){return `<div class="hb-navbar-start header-brand"><button class="hb-btn hb-btn-ghost hb-btn-square header-menu" data-action="toggle-nav" aria-label="${state.navCollapsed?'Expand':'Collapse'} navigation" aria-controls="desktop-navigation" aria-expanded="${!state.navCollapsed}">${icon('panel')}</button><a class="brand" href="#home" aria-label="Housebets"><img src="assets/house-avatar.jpg" width="26" height="26" alt=""><span>Housebets</span></a></div><div class="hb-navbar-center header-center"><button class="weekly-prize" data-action="prize">${icon('trophy')}<span><small>Weekly prize</small><b>$10,000.00</b></span></button><button class="hb-btn hb-btn-ghost hb-btn-square crown-button" data-action="prize" aria-label="Weekly prize details">${icon('crown')}</button></div><div class="hb-navbar-end header-actions"><button class="header-balance" data-action="settings" aria-label="Demo balance and currency settings"><span class="balance-token" aria-hidden="true">T</span><span><small>Demo balance</small><b data-wallet-balance>${amount(state.balance)}</b></span></button><button class="hb-btn hb-btn-ghost hb-btn-square" data-action="search" aria-label="Search matches">${icon('search')}</button>${state.demoMember?`<button class="hb-btn hb-btn-soft header-account" data-action="account" aria-label="Demo account">${icon('user')}<span>Demo account</span></button>`:`<button class="hb-btn hb-btn-soft header-login" data-action="login">Log In</button><button class="hb-btn hb-btn-primary header-register" data-action="register" aria-label="Register">${icon('user')}<span>Register</span></button>`}</div>`;}
function drawHeader(){const header=$('#site-header');if(header)header.innerHTML=headerContent();}
function syncShell(){document.body.classList.toggle('nav-collapsed',state.navCollapsed);document.body.classList.toggle('slip-collapsed',state.slipCollapsed);const toggle=$('#site-header [data-action=toggle-nav]');if(toggle){const mobile=innerWidth<=760;toggle.setAttribute('aria-label',mobile?'Open navigation':(state.navCollapsed?'Expand':'Collapse')+' navigation');toggle.setAttribute('aria-controls',mobile?'overlay':'desktop-navigation');toggle.setAttribute('aria-expanded',String(mobile?$('#overlay').open&&overlayKind==='browse':!state.navCollapsed));}}
function drawSidebar(){const sidebar=$('#desktop-navigation');if(!sidebar)return;const scroll=$('.sidebar-scroll',sidebar)?.scrollTop||0;sidebar.innerHTML=sidebarContent();$('.sidebar-scroll',sidebar).scrollTop=scroll;$$('.phone-navigation [data-section-route]').forEach(link=>link.href=sectionLink(link.dataset.sectionRoute));}
function waveBanner(){return `<section class="promotion-banner ${state.wavePaused?'wave-paused':''}" data-ambient aria-label="Wave 2 promotion"><div class="promotion-copy"><span class="wave-kicker">Wave 2. Available now.</span><h2>Catch Wave 2.</h2><button class="hb-btn hb-btn-soft hb-btn-sm promotion-button" data-action="wave">Discover Wave 2</button></div><div class="wave-art-frame"><img class="promotion-art" src="assets/house-wave2.png" width="600" height="200" alt="Hubie surfing the Housebets Wave 2"></div><span class="wave-light" aria-hidden="true"></span><button class="wave-motion-toggle icon-btn" data-action="wave-motion" aria-label="${state.wavePaused?'Play':'Pause'} banner gradient" aria-pressed="${state.wavePaused}">${icon(state.wavePaused?'play':'pause')}</button></section>`;}

function shell() {
  $('#app').innerHTML=`<header id="site-header" class="site-header hb-navbar" aria-label="Housebets header"></header><aside class="left-sidebar" aria-label="Sportsbook navigation" id="desktop-navigation"></aside><div class="site-canvas"><div id="promotion-slot"></div><div class="application-body"><main id="page" tabindex="-1"></main><aside id="bet-panel" class="desktop-bet-panel" aria-label="Bet slip"></aside></div><footer class="site-footer"><button data-action="settings">Display settings</button></footer></div><nav class="phone-navigation" aria-label="Phone navigation"><button class="phone-menu" data-action="browse">${icon('menu')}<span>Menu</span></button>${[['live','live','Live'],['following','star','Following'],['bets','ticket','My bets']].map(([page,symbol,name])=>`<a href="#${page}" data-route="${page}" data-section-route="${page}">${icon(symbol)}<span>${name}</span></a>`).join('')}<button data-action="slip"><span>Bet slip <b class="count-badge hb-badge hb-badge-sm" data-count>${state.slip.length}</b></span><small id="phone-stake">No selections</small></button></nav><button class="tablet-slip" data-action="slip">${icon('ticket')}<span>Bet slip</span><b class="count-badge hb-badge hb-badge-sm" data-count>${state.slip.length}</b></button>`;
  drawHeader();syncShell();navigate();
}
function navigate() {
  const [path,query='']=(location.hash.slice(1)||'home').split('?'), [page,mid]=path.split('/'), params=new URLSearchParams(query);
  const focusContent=!!document.activeElement?.closest('a[href^="#"]')||$('#overlay').open;
  closeOverlay(); state.page=['home','live','football','match','bets','following'].includes(page)?page:'home'; state.mid=matches.some(match=>match.id===mid)?mid:'ars';
  state.section=state.page==='match'?(matchById(state.mid).sport==='Esports'?'esports':'sports'):state.page==='football'?'sports':params.get('section')==='esports'?'esports':['bets','following'].includes(state.page)?state.section:'sports';
  state.game=state.section==='esports'&&games.includes(params.get('game'))?params.get('game'):'All games';
  state.query=''; state.sport=state.page==='football'?'Football':params.get('sport')||'All sports'; if (!sports.some(([name])=>name===state.sport)) state.sport='All sports';
  state.competition=params.get('competition')||'All competitions'; if (![...leagues,...esportLeagues,'Coastal Open','City League','All competitions'].includes(state.competition)) state.competition='All competitions';
  state.timing=state.page==='live'?'live':'all';state.favouriteFilter='All favourites';state.group='Popular';state.marketQuery='';state.dayFilter='all';drawPage(true);if(focusContent)requestAnimationFrame(()=>$('#page').focus({preventScroll:true}));window.scrollTo({top:0,behavior:'instant'});
}
function drawPage(animate=false) {
  document.body.dataset.page=state.page;$('#promotion-slot').innerHTML=state.page==='home'?waveBanner():'';syncShell();
  $('#page').innerHTML=({home,live,football,following,match:matchPage,bets:myBets}[state.page])();
  document.title=({home:'Sportsbook',live:'Live',football:'Football',match:`${matchById(state.mid).home} v ${matchById(state.mid).away}`,bets:'My bets',following:'Following'}[state.page])+' — Housebets';
  const active=state.page==='match'?(matchById(state.mid).sport==='Football'?'football':'live'):state.page;
  drawSidebar();$$('[data-route]').forEach(link=>{link.classList.toggle('on',link.dataset.route===active);if(link.dataset.route===active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});updateAccount();drawBetPanel();syncQuickState();updateNotifications();setupCarousel();watchLive();watchAmbient();if(animate)reveal($('.page-title')||$('.event-scoreboard'));
}
function drawFixtures() { const root=$('#fixtures'); if(root) root.innerHTML=fixtureResults();syncQuickState();watchLive();if(root)reveal($('.competition-section',root)||root.firstElementChild); }
function updateAccount(){
 $$('.header-balance').forEach(node=>node.setAttribute('aria-label','Demo balance '+money(state.balance)+'. Open display settings'));
 $$('[data-count]').forEach(node=>node.textContent=state.slip.length);$$('[data-wallet-balance]').forEach(node=>node.innerHTML=amount(state.balance));$$('[data-open-bets]').forEach(node=>node.textContent=state.bets.filter(b=>b.status==='Open').length);
 const launcher=$('.phone-navigation>[data-action="slip"]');
 if(launcher){launcher.innerHTML=state.betMode==='quick'?`<span>Quick Bet</span><small id="phone-stake">${quickActive()?money(state.quickStake):'Set amount'}</small>`:`<span>Bet slip <b class="count-badge hb-badge hb-badge-sm" data-count>${state.slip.length}</b></span><small id="phone-stake">${state.slip.some(item=>item.stake)?money(state.slip.reduce((sum,item)=>sum+item.stake,0)):state.slip.length?'Add stake':'No selections'}</small>`;const confirmed=state.betMode==='quick'?state.lastQuick:!state.slip.length&&state.lastPlaced;if(confirmed)launcher.innerHTML='<span>Bet placed</span><small>View receipt</small>';launcher.classList.toggle('quick-launcher',quickActive());}
}
function syncQuickState(){
 const active=quickActive();document.body.classList.toggle('quick-active',active);
 $$('[data-pick]').forEach(button=>{const match=matchById(button.dataset.mid),name=selectedName(match,button.dataset.label),boost=boostFor(match)?.market===button.dataset.market&&match.boost.label===button.dataset.label?boostFor(match):null;button.setAttribute('aria-label',`${active?'Quick bet '+money(state.quickStake)+' on ':''}${name}, ${button.disabled?'suspended':(boost?'boosted from '+boost.original.toFixed(2)+' to ':'')+Number(button.dataset.price).toFixed(2)}`);});
 const hint=$('#quick-status');if(hint){hint.textContent=active?`Quick Bet is on. Each odds tap places ${money(state.quickStake)}.`:'Set an amount to enable one-tap bets.';hint.classList.toggle('active',active);}updateAccount();
}

function updateCurrency() { $$('[data-usdt]').forEach(node=>node.textContent=money(node.dataset.usdt));updateAccount(); }
function updatePicked(key) { $$(`[data-pick="${CSS.escape(key)}"]`).forEach(button=>{const picked=state.slip.some(item=>item.key===key);button.classList.toggle('is-picked',picked);button.setAttribute('aria-pressed',picked);});updateAccount(); }

function currencyControls(scope='panel'){return `<div class="currency-controls"><label class="setting-toggle"><span><b>Display in fiat</b><small>Convert displayed amounts automatically</small></span><input class="hb-toggle hb-toggle-sm" id="fiat-${scope}" data-setting="fiat" type="checkbox" ${state.fiat?'checked':''}></label><label class="setting-field"><span>Display currency</span><select class="hb-select hb-select-sm" id="currency-${scope}" data-setting="currency">${Object.entries(currencies).map(([code,data])=>`<option value="${code}" ${state.currency===code?'selected':''}>${code} &middot; ${data.symbol}</option>`).join('')}</select></label><label class="setting-toggle motion-setting"><span><b>Reduce animations</b><small>Keep interface movements to a minimum</small></span><input class="hb-toggle hb-toggle-sm" id="motion-${scope}" data-setting="reduceMotion" type="checkbox" ${state.reduceMotion?'checked':''}></label><p class="conversion-note">Illustrative rate: 1 USDT = ${currencies[state.currency].symbol}${currencies[state.currency].rate.toFixed(2)}. Bets are stored in USDT.</p></div>`;}

function slipLine(item,index) {
 const match=matchById(item.mid),suspended=!!item.suspended;
 return `<article class="slip-line ${suspended?'is-suspended':''}"><div class="slip-event"><a href="#match/${match.id}">${match.home} v ${match.away}</a><button class="hb-btn hb-btn-ghost hb-btn-square hb-btn-sm icon-btn" data-remove="${index}" aria-label="Remove ${html(selectedName(match,item.label))}">${icon('close')}</button></div><div class="slip-selection">${selectionBadge(match,item.label)}<div><b>${html(selectedName(match,item.label))}</b><span>${html(item.market)}</span></div><strong>${suspended?icon('lock'):item.price.toFixed(2)}</strong></div>${item.changed?`<div class="alert warning">Odds changed: ${item.oldPrice.toFixed(2)} to ${item.price.toFixed(2)}<button data-accept="${index}">Accept updated odds</button></div>`:''}${suspended?`<p class="selection-paused" role="status">${icon('lock')}Selection suspended. Remove it or wait for betting to resume.</p>`:''}<label class="stake-entry hb-input"><span>Stake <small>${denomination()}</small></span><input type="number" inputmode="decimal" min="0" step="0.01" id="stake-${index}" data-stake="${index}" aria-required="true" aria-describedby="panel-error" aria-label="Stake in ${denomination()} for ${html(selectedName(match,item.label))}" placeholder="0.00" value="${item.stake?+(item.stake*conversion()).toFixed(2):''}" ${suspended?'disabled':''}></label><div class="stake-picks">${[5,10,25,50].map(value=>`<button data-add-stake="${index}|${value}" aria-label="Add ${money(value)} to stake" ${suspended?'disabled':''}>${presetLabel(value)}</button>`).join('')}</div><div class="selection-return"><span>Potential return</span><b data-return="${index}">${money(item.stake*item.price)}</b></div>${state.fiat?`<p class="underlying" data-underlying="${index}">${item.stake.toFixed(2)} USDT stake</p>`:''}</article>`;
}
function slipContent(){
 const quick=state.betMode==='quick',receipt=quick?(state.lastQuick?{bets:[state.lastQuick]}:null):(!state.slip.length?state.lastPlaced:null),total=state.slip.reduce((sum,item)=>sum+item.stake,0),returns=state.slip.reduce((sum,item)=>sum+item.stake*item.price,0),canClear=!receipt&&(quick?state.quickStake>0:state.slip.length>0),paused=state.slip.some(item=>!!item.suspended);
 return `<div class="panel-wrap ${quick?'quick-panel':''} ${receipt?'has-receipt':''}"><div class="panel-head"><h2>Bet slip ${receipt?'':`<b class="count-badge hb-badge hb-badge-sm" data-count>${state.slip.length}</b>`}</h2><div><button class="hb-btn hb-btn-ghost hb-btn-square hb-btn-sm icon-btn panel-collapse" data-action="collapse-slip" aria-label="Collapse bet slip" aria-expanded="true" title="Collapse bet slip">${icon('panel')}</button>${canClear?`<button class="hb-btn hb-btn-ghost hb-btn-square hb-btn-sm icon-btn" data-action="clear-slip" aria-label="${quick?'Clear Quick Bet amount':'Clear bet slip'}">${icon('trash')}</button>`:''}<button class="hb-btn hb-btn-ghost hb-btn-square hb-btn-sm icon-btn panel-close" data-action="close" aria-label="Close bet slip">${icon('close')}</button></div></div><nav class="bet-mode-tabs hb-tabs hb-tabs-box" role="tablist" aria-label="Bet mode"><button role="tab" id="bet-mode-single" aria-controls="bet-mode-content" data-bet-mode="single" tabindex="${quick?-1:0}" aria-selected="${!quick}" class="hb-tab ${quick?'':'active hb-tab-active'}">Single Bet</button><button role="tab" id="bet-mode-quick" aria-controls="bet-mode-content" data-bet-mode="quick" tabindex="${quick?0:-1}" aria-selected="${quick}" class="hb-tab ${quick?'active hb-tab-active':''}">Quick Bet</button></nav><div class="panel-flow" id="bet-mode-content" role="tabpanel" aria-labelledby="bet-mode-${quick?'quick':'single'}"><div class="bet-panel-body"><div id="panel-error" class="panel-error" role="alert" ${quick&&state.quickError?'':'hidden'}>${quick?html(state.quickError):''}</div>${receipt?placedReceipt(receipt,quick):quick?`<section class="quick-workspace"><label class="quick-amount-field hb-input"><span>Bet amount <small>${denomination()}</small></span><input id="quick-amount" aria-describedby="quick-status" type="number" inputmode="decimal" min="0" step="0.01" placeholder="0.00" value="${state.quickStake?+(state.quickStake*conversion()).toFixed(2):''}" aria-label="Quick Bet amount in ${denomination()}"></label><p id="quick-status" class="quick-status ${quickActive()?'active':''}">${quickActive()?`Quick Bet is on. Each odds tap places ${money(state.quickStake)}.`:'Set an amount to enable one-tap bets.'}</p><p class="quick-help">Tap marked odds to place a bet instantly.</p></section>`:`<div class="panel-selections">${state.slip.length?state.slip.map(slipLine).join(''):empty('Your slip is empty','Choose odds to add your first selection.',`<a class="hb-btn hb-btn-soft hb-btn-sm" href="${sectionLink('live')}">Browse live matches</a>`)}</div>`}</div>${!quick&&state.slip.length?`<div class="panel-summary"><div><span>Total stake</span><b id="total-stake">${money(total)}</b></div><div><span>Potential return</span><b id="total-return">${money(returns)}</b></div><button class="hb-btn hb-btn-primary place-btn" data-action="place" ${paused?'disabled':''}>Place bet <span id="place-amount">${money(total)}</span></button>${paused?'<p class="suspended-action-note">Remove the suspended selection or wait for betting to resume.</p>':'<p>Simulated funds only</p>'}</div>`:''}<div class="panel-after-action"><details class="panel-settings"><summary>Display settings ${icon('settings')}</summary>${currencyControls()}</details><details class="prototype-controls"><summary>Prototype scenarios</summary><button data-scenario="odds" ${state.slip.length?'':'disabled'}>Change odds</button><button data-scenario="suspend" ${state.slip.length?'':'disabled'}>${state.slip[0]&&(state.slip[0].suspended)?'Resume selection':'Suspend selection'}</button><button data-scenario="fail">${state.fail?'Failure queued':'Fail next bet'}</button></details></div></div></div>`;
}
function placedReceipt(receipt,quick){
 const bets=receipt.bets;
 return `<section class="placed-receipt" aria-label="${bets.length===1?'Bet placed':'Bets placed'}"><img src="assets/mascot-thumbs-up.png" width="152" height="152" alt="Housebets sloth giving a thumbs-up" decoding="async"><h2 tabindex="-1" data-receipt-heading>${bets.length===1?'Bet placed!':'Bets placed!'}</h2><p class="receipt-status" role="status">${bets.length===1?'Your bet is confirmed.':bets.length+' separate bets confirmed.'}</p>${quick?`<p class="receipt-quick-status">Quick Bet stays on at ${money(state.quickStake)} per pick.</p>`:''}<div class="receipt-bets">${bets.map(bet=>{const match=matchById(bet.mid);return `<article class="receipt-bet"><div class="receipt-pick">${selectionBadge(match,bet.label)}<span><b>${html(bet.label)}</b><small>${html(bet.market)}</small></span><strong>${bet.price.toFixed(2)}</strong></div><p>${html(match.home)} v ${html(match.away)}</p><dl><div><dt>Stake</dt><dd>${money(bet.stake)}</dd></div><div><dt>Potential return</dt><dd>${money(bet.stake*bet.price)}</dd></div></dl><small class="receipt-reference">${bet.id}</small></article>`;}).join('')}</div><button class="hb-btn hb-btn-primary receipt-new" data-action="new-bet">Place a new bet</button><button class="receipt-my-bets" data-action="my-bets">View my bets</button></section>`;
}
function drawBetPanel(){
 const dock=$('#bet-panel');if(!dock)return;
 if(desktopPanel.matches&&state.slipCollapsed){dock.innerHTML=`<button class="slip-rail" data-action="expand-slip" aria-label="Expand bet slip" title="Expand bet slip">${icon('ticket')}<b class="count-badge hb-badge hb-badge-sm" data-count>${state.slip.length}</b><span>Bet slip</span>${icon('panel')}</button>`;return;}
 const target=desktopPanel.matches?dock:($('#overlay').open&&overlayKind==='slip'?$('#overlay'):null);
 if(!desktopPanel.matches)dock.innerHTML='';
 if(!target)return;
 const previousMode=$('[data-bet-mode][aria-selected=true]',target)?.dataset.betMode,settingsOpen=$('.panel-settings',target)?.open,scenariosOpen=$('.prototype-controls',target)?.open,scroll=$('.panel-flow',target)?.scrollTop||0;
 target.innerHTML=slipContent();slideBetMode($('.bet-mode-tabs',target),previousMode,state.betMode);if(settingsOpen)$('.panel-settings',target).open=true;if(scenariosOpen&&$('.prototype-controls',target))$('.prototype-controls',target).open=true;if($('.panel-flow',target))$('.panel-flow',target).scrollTop=scroll;
}

function searchResults(query=''){const results=matches.filter(match=>inSection(match)&&`${match.home} ${match.away} ${match.game||''} ${match.league} ${match.sport} match result goals`.toLowerCase().includes(query.toLowerCase()));return results.length?results.map(match=>`<a class="search-result" href="#match/${match.id}">${badge(match)}<span><b>${match.home} v ${match.away}</b><small>${match.game||match.sport} · ${match.league}</small></span><span class="search-result-time">${match.live?'LIVE':match.clock}</span></a>`).join(''):'<p class="search-empty">No matches found. Try a team, game, or competition.</p>';}
function overlayTitle(kind){const titles={'account':'Demo account','prize':'Weekly prize','help':'How betting works','market-info':state.infoMarket,'share':'Match link','cashout':'Confirm cash out'};if(titles[kind])return titles[kind];return kind==='hubie'?'Hubie':kind==='slip'?'Bet slip':kind==='settings'?'Settings':kind==='browse'?'Browse sports':kind==='notifications'?'Notifications':kind==='search'?'Find your match':'Wave 2';}

function overlayContent(kind) {
 if(kind==='cashout')return cashoutReview();
 if(kind==='account')return `<div class="account-preview"><img src="assets/mascot.jpg" width="88" height="88" alt="Hubie"><h3>${state.demoMember?'Welcome home.':'Your seat is ready.'}</h3><p>Explore the full sportsbook with a demo balance. No sign-up or deposit is needed for this prototype.</p><div class="account-demo-balance"><small>Demo balance</small><b>${amount(state.balance)}</b></div><button class="hb-btn hb-btn-primary" data-action="${state.demoMember?'close':'demo-login'}">${state.demoMember?'Continue browsing':'Continue in demo'}</button>${state.demoMember?'<button class="account-leave" data-action="demo-logout">Leave demo account</button>':''}</div>`;
 if(kind==='prize')return `<div class="prize-preview">${icon('trophy')}<span class="prize-preview-kicker">THE HOUSE WEEKLY</span><h3>$10,000.00</h3><p>A preview of the weekly prize area from the Housebets header. No prize, entry or reward is available in this prototype.</p><a class="hb-btn hb-btn-primary" href="#home">Explore sports</a></div>`;
 if(kind==='help')return `<div class="help-content"><h3>A single, from pick to payout.</h3><ol><li><b>Find your match</b><p>Browse live games, upcoming fixtures or your favourites.</p></li><li><b>Choose an outcome</b><p>Tap its odds, then enter a stake in your bet slip.</p></li><li><b>Review before placing</b><p>Check the selection, accepted odds, stake and potential return.</p></li><li><b>Keep track in My bets</b><p>Follow open bets, review settled results or cash out when offered.</p></li></ol><p class="help-note">Quick Bet places immediately at your set amount while its tab is active. This prototype uses simulated funds.</p></div>`;
 if(kind==='market-info')return `<div class="market-explanation"><h3>${html(state.infoMarket)}</h3><p>${state.infoMarket==='Match result'?'Pick the home win, a draw, or the away win. Football match-result bets cover regular time plus stoppage time.':state.infoMarket.includes('Total')?'Pick whether the final total will be over or under the displayed line. Half-point lines cannot end in a tie.':'Choose the outcome shown in the market. Your slip shows the accepted odds, stake and potential return before you place a bet.'}</p><p class="help-note">All outcomes and prices shown here are sample data.</p><button class="hb-btn hb-btn-soft" data-action="close">Got it</button></div>`;
 if(kind==='share')return `<div class="market-explanation"><p>Copy this link to return to the match.</p><label class="hb-input"><span class="sr-only">Match link</span><input readonly value="${html(location.href)}" onclick="this.select()"></label></div>`;

  if(kind==='hubie')return `<div class="hubie-intro"><button class="hubie-greet" data-action="hubie-greet" aria-label="Say hello to Hubie"><img src="assets/mascot.jpg" width="124" height="124" alt=""></button><h3>Hey, I’m Hubie.</h3><p class="hubie-message" role="status">Your Housebets host. Ready to find your next match?</p><a class="hb-btn hb-btn-primary hubie-explore" href="${sectionLink('live')}">Explore live matches</a><button class="hubie-my-bets" data-action="my-bets">View my bets</button></div>`;
  if(kind==='slip')return slipContent();
  if(kind==='browse')return sidebarContent(true);
  if(kind==='search')return `<div class="nav-search-field hb-input">${icon('search')}<input id="nav-search" type="search" autocomplete="off" placeholder="Search teams or competitions" aria-label="Search matches"></div><div id="nav-search-results">${searchResults()}</div>`;
  if(kind==='notifications')return notificationsContent();
  if(kind==='settings')return `<div class="standalone-settings"><h2>Numbers your way.</h2><p>Choose how your demo balance, stakes and returns are displayed.</p>${currencyControls('modal')}</div>`;
  return `<div class="wave-detail"><img src="assets/house-wave2.png" width="600" height="200" alt="Wave2 sloth surfing a cyan wave"><span class="eyebrow">AVAILABLE NOW</span><h2>Meet the next wave.</h2><p>Wave 2 is the current Housebets community promotion.</p><p>This is a visual prototype. No rewards or real funds are available.</p><button class="hb-btn hb-btn-primary" data-action="close">Back to sport</button></div>`;
}
function openOverlay(kind='slip'){
 if(kind!=='cashout')state.pendingCashout=null;else{$('#notice').classList.remove('show');clearTimeout(noticeTimer);}
 if(kind==='slip'&&desktopPanel.matches){state.slipCollapsed=false;syncShell();save();drawBetPanel();$('#bet-panel').classList.remove('panel-attention');return;}
 const overlay=$('#overlay');if(!overlay.open)previousFocus=document.activeElement;
 overlayKind=kind;overlay.dataset.kind=kind;
 overlay.setAttribute('aria-label',overlayTitle(kind));
 if(kind==='notifications'){$('#settlement-alert').classList.remove('show');clearTimeout(settlementTimer);state.notifications.forEach(item=>item.read=true);save();updateNotifications();}
 drawOverlay();if(!overlay.open){overlay.showModal();document.body.classList.add('modal-open');}syncShell();
 requestAnimationFrame(()=>{if(kind==='cashout')$('[data-action=cancel-cashout]',overlay)?.focus();else if(kind==='search')$('#nav-search')?.focus();else $('[data-action="close"]',overlay)?.focus();if(kind==='hubie')greetHubie($('.hubie-greet img',overlay));if(kind==='browse')greetHubie($('.hubie-launcher img',overlay));});
}

function drawOverlay(){
 const overlay=$('#overlay');if(overlayKind==='slip'){const settingsOpen=$('.panel-settings',overlay)?.open,scroll=$('.panel-flow',overlay)?.scrollTop||0;overlay.innerHTML=slipContent();slideBetMode($('.bet-mode-tabs',overlay),null,state.betMode);if(settingsOpen)$('.panel-settings',overlay).open=true;if($('.panel-flow',overlay))$('.panel-flow',overlay).scrollTop=scroll;return;}
 if(overlayKind==='browse'){overlay.innerHTML=sidebarContent(true);updateNotifications();watchLive(overlay);return;}
 overlay.innerHTML=`<div class="overlay-head"><h2>${overlayTitle(overlayKind)}</h2><button class="hb-btn hb-btn-ghost hb-btn-square hb-btn-sm icon-btn" data-action="close" aria-label="Close popup">${icon('close')}</button></div>${overlayContent(overlayKind)}`;
}

function closeOverlay() { const overlay=$('#overlay');if(overlay?.open)overlay.close(); }
function updateTotals() {
  state.slip.forEach((item,index)=>{const result=$(`[data-return="${index}"]`);if(result)result.textContent=money(item.stake*item.price);const underlying=$(`[data-underlying="${index}"]`);if(underlying)underlying.textContent=`${item.stake.toFixed(2)} USDT stake`;});
  const total=state.slip.reduce((sum,item)=>sum+item.stake,0),returns=state.slip.reduce((sum,item)=>sum+item.stake*item.price,0);
  if($('#total-stake'))$('#total-stake').textContent=money(total);if($('#total-return'))$('#total-return').textContent=money(returns);if($('#place-amount'))$('#place-amount').textContent=money(total);updateAccount();save();
}
function error(message){$$('[data-stake]').forEach(input=>input.setAttribute('aria-invalid',String(!state.slip[+input.dataset.stake]?.stake)));const target=$('#panel-error');if(target){target.hidden=false;target.textContent=message;reveal(target);target.scrollIntoView({block:'nearest',behavior:'instant'});}else notify(message);}

function place(){
 if(!state.slip.length)return;
 if(state.slip.some(item=>item.changed))return error('Accept the updated odds before placing your bet.');
 if(state.slip.some(item=>!!item.suspended))return error('A selection is suspended. Remove it or wait for the market to reopen.');
 if(state.slip.some(item=>!Number.isFinite(item.stake)||item.stake<.01))return error('Enter at least 0.01 USDT for each bet.');
 const total=state.slip.reduce((sum,item)=>sum+item.stake,0);if(total>state.balance)return error('Not enough demo balance for this stake.');
 if(state.fail){state.fail=false;return error('Bet failed. Your stake was not deducted. Try again.');}
 const keys=state.slip.map(item=>item.key),count=state.slip.length;
 state.slip.forEach((item,index)=>state.bets.unshift({id:`HB${Date.now().toString().slice(-7)}${index}`,mid:item.mid,label:selectedName(matchById(item.mid),item.label),market:item.market,price:item.price,stake:item.stake,status:'Open'}));
 state.lastPlaced={bets:state.bets.slice(0,count).map(bet=>({...bet}))};state.balance=+(state.balance-total).toFixed(2);state.slip=[];state.panelMessage=count===1?'Bet placed':'Bets placed';save();keys.forEach(updatePicked);if(state.page==='bets')drawPage();drawBetPanel();requestAnimationFrame(()=>{const flow=$('.panel-flow');if(flow)flow.scrollTop=0;$('[data-receipt-heading]')?.focus({preventScroll:true});celebrate($('.placed-receipt>img'));});notify(state.panelMessage,'success');
}
function quickFailure(message){state.lastQuick=null;state.lastPlaced=null;save();state.quickError=message;drawBetPanel();notify(message,'error');}
function placeQuick(button){
 if(!quickActive())return;
 const price=Number(button.dataset.price),stake=state.quickStake;
 if(button.disabled||!Number.isFinite(price)||price<=1)return quickFailure('Betting is suspended for this selection.');
 if(stake>state.balance)return quickFailure('Not enough demo balance. Lower your Quick Bet amount.');
 if(state.fail){state.fail=false;return quickFailure('Bet failed. Your stake was not deducted. Try again.');}
 const match=matchById(button.dataset.mid),bet={id:`HB${Date.now().toString().slice(-8)}${state.bets.length}`,mid:match.id,label:selectedName(match,button.dataset.label),market:button.dataset.market,price,stake,status:'Open',quick:true};
 state.bets.unshift(bet);state.balance=+(state.balance-stake).toFixed(2);state.lastQuick=bet;state.lastPlaced={bets:[{...bet}]};state.quickError='';state.panelMessage='';save();updateAccount();if(state.page==='bets')drawPage();drawBetPanel();const flow=$('.panel-flow');if(flow)flow.scrollTop=0;celebrate($('.placed-receipt>img'));pop(button);notify(`Bet placed: ${bet.label}`,'success');
}

document.addEventListener('click',event=>{
  const button=event.target.closest('button,a');if(!button)return;
  if(button.classList.contains('skip-link')){event.preventDefault();$('#page').focus();return;}
  if(button.dataset.saveMarket){const key=button.dataset.saveMarket;state.savedMarkets=state.savedMarkets.includes(key)?state.savedMarkets.filter(item=>item!==key):[...state.savedMarkets,key];save();drawMarkets(false);requestAnimationFrame(()=>$$('[data-save-market]').find(node=>node.dataset.saveMarket===key)?.focus({preventScroll:true}));return;}
  if(button.dataset.marketInfo){state.infoMarket=button.dataset.marketInfo;openOverlay('market-info');return;}
  if(button.dataset.carousel){moveCarousel(Number(button.dataset.carousel));return;}
  if(button.dataset.favouriteFilter){state.favouriteFilter=button.dataset.favouriteFilter;$$('[data-favourite-filter]').forEach(item=>{const active=item.dataset.favouriteFilter===state.favouriteFilter;item.setAttribute('aria-pressed',active);(item.closest('.favourite-chip')||item).classList.toggle('active',active);});drawFixtures();return;}
  if(button.dataset.unfollow){state.follow=state.follow.filter(name=>name!==button.dataset.unfollow);if(!state.follow.includes(state.favouriteFilter))state.favouriteFilter='All favourites';save();drawPage();requestAnimationFrame(()=>($('.favourite-all')||$('.following-onboarding button'))?.focus({preventScroll:true}));return;}
  if(button.dataset.pick){
    if(state.betMode==='quick'){if(quickActive())placeQuick(button);else notify('Set a Quick Bet amount first');return;}
    if(button.disabled)return;warmReceiptArt();state.lastPlaced=null;state.lastQuick=null;state.panelMessage='';
    const key=button.dataset.pick,index=state.slip.findIndex(item=>item.key===key);
    if(index>=0){state.slip.splice(index,1);notify('Selection removed');}else{state.slip.push({key,mid:button.dataset.mid,label:button.dataset.label,market:button.dataset.market,price:+button.dataset.price,stake:0});notify('Added to bet slip');}
    updatePicked(key);drawBetPanel();save();pop(button);$$('[data-count]').forEach(pop);const selection=$('.slip-line:last-child');if(index<0)reveal(selection);return;
  }
  if(button.dataset.sport){if(state.page==='home'&&button.dataset.sport==='Football'){location.hash='football';return;}state.sport=button.dataset.sport;state.competition='All competitions';$$('[data-sport]').forEach(item=>{const on=item.dataset.sport===state.sport;item.classList.toggle('on',on);item.setAttribute('aria-pressed',on);});if($('#competition'))$('#competition').value=state.competition;drawFixtures();return;}
  if(button.dataset.game){state.game=button.dataset.game;state.competition='All competitions';drawPage(true);return;}
  if(button.dataset.timing){state.timing=button.dataset.timing;$$('[data-timing]').forEach(item=>{const on=item.dataset.timing===state.timing;item.classList.toggle('on',on);item.setAttribute('aria-pressed',on);});drawFixtures();return;}
  if(button.dataset.competition){state.competition=button.dataset.competition;$$('[data-competition]').forEach(item=>{const on=item.dataset.competition===state.competition;item.classList.toggle('on',on);item.setAttribute('aria-pressed',on);});if($('#competition'))$('#competition').value=state.competition;drawFixtures();return;}
  if(button.dataset.follow){const name=button.dataset.follow;state.follow=state.follow.includes(name)?state.follow.filter(item=>item!==name):[...state.follow,name];$$('[data-follow]').filter(item=>item.dataset.follow===name).forEach(item=>{const followed=state.follow.includes(name);item.classList.toggle('is-followed',followed);item.setAttribute('aria-pressed',followed);item.setAttribute('aria-label',(followed?'Unfollow ':'Follow ')+name);const text=$('span',item);if(text)text.textContent=(followed?'Following ':'Follow ')+name;});$$('[data-follow-count]').forEach(node=>node.textContent=state.follow.length);pop($('.symbol',button));save();if(state.page==='following'){if(!state.follow.includes(state.favouriteFilter))state.favouriteFilter='All favourites';drawPage();requestAnimationFrame(()=>$('.favourite-all')?.focus({preventScroll:true}));}return;}
  if(button.dataset.group){state.group=button.dataset.group;$$('[data-group]').forEach(item=>{const on=item.dataset.group===state.group;item.classList.toggle('on',on);item.setAttribute('aria-pressed',on);});if($('#market-group'))$('#market-group').value=state.group;drawMarkets();return;}
  if(button.dataset.history){state.history=button.dataset.history;$$('[data-history]').forEach(item=>{const on=item.dataset.history===state.history;item.classList.toggle('on',on);item.setAttribute('aria-pressed',on);});$('#history').innerHTML=betHistory();reveal($('.activity',$('#history'))||$('#history').firstElementChild);return;}
  if(button.dataset.betMode){if(button.dataset.betMode==='quick')warmReceiptArt();state.betMode=button.dataset.betMode;state.panelMessage='';drawBetPanel();syncQuickState();$('[data-bet-mode='+state.betMode+']')?.focus({preventScroll:true});return;}
  if(button.dataset.notification){const note=state.notifications.find(item=>item.id===button.dataset.notification);if(note){note.read=true;save();updateNotifications();}$('#settlement-alert').classList.remove('show');closeOverlay();state.history='Settled';if(location.hash==='#bets')drawPage();else location.hash='bets';return;}
  if(button.dataset.remove!==undefined){const [removed]=state.slip.splice(+button.dataset.remove,1);drawBetPanel();updatePicked(removed.key);save();return;}
  if(button.dataset.addStake){const [index,value]=button.dataset.addStake.split('|').map(Number);state.slip[index].stake=+((state.slip[index].stake||0)+value).toFixed(2);$(`#stake-${index}`).value=+(state.slip[index].stake*conversion()).toFixed(2);updateTotals();return;}
  if(button.dataset.accept!==undefined){const accepted=+button.dataset.accept;state.slip[accepted].changed=false;drawBetPanel();$(`#stake-${accepted}`)?.focus({preventScroll:true});pop($$('.slip-selection>strong')[accepted]);save();return;}
  if(button.dataset.scenario){const item=state.slip[0];if(button.dataset.scenario==='fail')state.fail=!state.fail;else if(item&&button.dataset.scenario==='odds'){item.oldPrice=item.price;item.price=+(item.price+.12).toFixed(2);item.changed=true;}else if(item&&button.dataset.scenario==='suspend'){item.suspended=!item.suspended;}drawBetPanel();const controls=$('.prototype-controls',desktopPanel.matches?$('#bet-panel'):$('#overlay'));if(controls)controls.open=true;save();return;}
  if(button.dataset.cashout){const bet=state.bets.find(item=>item.id===button.dataset.cashout);if(!bet||bet.status!=='Open')return;state.pendingCashout={id:bet.id,offer:+(bet.stake*.85).toFixed(2)};openOverlay('cashout');return;}
  switch(button.dataset.action){
    case 'toggle-nav':if(innerWidth<=760)openOverlay('browse');else{state.navCollapsed=!state.navCollapsed;syncShell();save();requestAnimationFrame(updateCarousel);}break;
    case 'collapse-slip':state.slipCollapsed=true;syncShell();drawBetPanel();save();$('#bet-panel .slip-rail')?.focus({preventScroll:true});requestAnimationFrame(updateCarousel);break;
    case 'expand-slip':state.slipCollapsed=false;syncShell();drawBetPanel();save();$('#bet-panel [data-action=collapse-slip]')?.focus({preventScroll:true});requestAnimationFrame(updateCarousel);break;
    case 'reset-markets':state.group='Popular';state.marketQuery='';drawPage();break;
    case 'login':case 'register':case 'account':openOverlay('account');break;
    case 'demo-login':state.demoMember=true;save();closeOverlay();drawHeader();syncShell();notify('Demo account ready','success');break;
    case 'demo-logout':state.demoMember=false;save();closeOverlay();drawHeader();syncShell();break;
    case 'prize':openOverlay('prize');break;
    case 'help':openOverlay('help');break;
    case 'share-match':if(navigator.clipboard)navigator.clipboard.writeText(location.href).then(()=>notify('Match link copied','success')).catch(()=>openOverlay('share'));else openOverlay('share');break;
    case 'confirm-cashout':confirmCashout();break;
    case 'cancel-cashout':state.pendingCashout=null;closeOverlay();break;
    case 'slip':openOverlay('slip');break;
    case 'settings':openOverlay('settings');break;
    case 'notifications':openOverlay('notifications');break;
    case 'dismiss-settlement':$('#settlement-alert').classList.remove('show');break;
    case 'clear-slip':{if(state.betMode==='quick'){state.quickStake=0;state.lastQuick=null;state.quickError='';drawBetPanel();syncQuickState();save();break;}const keys=state.slip.map(item=>item.key);state.slip=[];state.lastPlaced=null;state.panelMessage='';keys.forEach(updatePicked);drawBetPanel();save();break;}
    case 'browse':openOverlay('browse');break;
    case 'hubie-pick':greetHubie($('.spotlight-hubie img'));break;
    case 'wave-motion':state.wavePaused=!state.wavePaused;$('.promotion-banner')?.classList.toggle('wave-paused',state.wavePaused);button.setAttribute('aria-label',`${state.wavePaused?'Play':'Pause'} banner gradient`);button.setAttribute('aria-pressed',state.wavePaused);button.innerHTML=icon(state.wavePaused?'play':'pause');break;
    case 'hubie':openOverlay('hubie');break;
    case 'hubie-greet':{const messages=['Follow a team or competition with its star. I’ll help keep your favourites close.','Pick odds on any match, and your selection will be ready in the slip.','Quick Bet uses the amount you set for each odds tap.'];const node=$('.hubie-message');const next=(Number(node.dataset.tip)||0)%messages.length;node.dataset.tip=next+1;node.textContent=messages[next];greetHubie($('.hubie-greet img'));break;}
    case 'search':openOverlay('search');break;
    case 'follows':location.hash=sectionLink('following');break;
    case 'wave':openOverlay('wave');break;
    case 'close':closeOverlay();break;
    case 'place':place();break;
    case 'new-bet':{state.lastPlaced=null;state.lastQuick=null;save();if(state.betMode==='quick'){state.lastQuick=null;state.quickError='';}else state.lastPlaced=null;state.panelMessage='';drawBetPanel();syncQuickState();if(!desktopPanel.matches)closeOverlay();requestAnimationFrame(()=>{const picks=$$('#page [data-pick]:not(:disabled)'),pick=picks.find(node=>{const box=node.getBoundingClientRect();return box.top>=0&&box.bottom<innerHeight-80;})||picks[0];if(pick){pick.focus({preventScroll:true});if(pick.getBoundingClientRect().bottom<0||pick.getBoundingClientRect().top>innerHeight-80)pick.scrollIntoView({block:'center',behavior:'instant'});}else location.hash=sectionLink().slice(1);});break;}
    case 'my-bets':closeOverlay();state.history='Open';if(location.hash==='#bets')drawPage();else location.hash='bets';break;
    case 'reset':state.query='';state.competition='All competitions';state.game='All games';state.sport=state.page==='football'?'Football':'All sports';drawPage();break;
    case 'nothing-live':state.noLive=!state.noLive;drawPage();break;
    case 'settle':{const bet=state.bets.find(item=>item.status==='Open');if(!bet)return notify('No open demo bets to settle.');bet.status='Won';bet.payout=+(bet.stake*bet.price).toFixed(2);state.balance=+(state.balance+bet.payout).toFixed(2);state.history='Settled';recordSettlement(bet);save();drawPage();break;}
  }
  if(button.tagName==='A'&&button.getAttribute('href')?.startsWith('#')&&button.hash===location.hash){event.preventDefault();navigate();}
});
document.addEventListener('input',event=>{
  const input=event.target;
  if(input.id==='finder'){state.query=input.value;cancelAnimationFrame(searchFrame);searchFrame=requestAnimationFrame(drawFixtures);}
  if(input.id==='market-search'){state.marketQuery=input.value;cancelAnimationFrame(searchFrame);searchFrame=requestAnimationFrame(()=>drawMarkets(false));}
  if(input.id==='nav-search'){$('#nav-search-results').innerHTML=searchResults(input.value);}
  if(input.dataset.stake!==undefined){input.removeAttribute('aria-invalid');state.slip[+input.dataset.stake].stake=Math.max(0,(Number(input.value)||0)/conversion());if($('#panel-error'))$('#panel-error').hidden=true;updateTotals();}
  if(input.id==='quick-amount'){state.quickStake=Math.max(0,(Number(input.value)||0)/conversion());state.quickError='';if($('#panel-error'))$('#panel-error').hidden=true;state.panelMessage='';syncQuickState();save();}
});
document.addEventListener('change',event=>{
  const input=event.target;
  if(input.id==='competition'){state.competition=input.value;$$('[data-competition]').forEach(item=>{const on=item.dataset.competition===state.competition;item.classList.toggle('on',on);item.setAttribute('aria-pressed',on);});drawFixtures();}
  if(input.id==='match-day'){state.dayFilter=input.value;drawFixtures();}
  if(input.id==='market-group'){state.group=input.value;$$('[data-group]').forEach(item=>{const on=item.dataset.group===state.group;item.classList.toggle('on',on);item.setAttribute('aria-pressed',on);});$('#markets').innerHTML=marketRows();reveal($('.market-row',$('#markets')));}
  
  if(input.dataset.setting){if(input.dataset.setting==='fiat')state.fiat=input.checked;else if(input.dataset.setting==='reduceMotion'){state.reduceMotion=input.checked;setReducedMotion(state.reduceMotion);}else state.currency=input.value;const id=input.id;drawBetPanel();if($('#overlay').open&&overlayKind==='settings')drawOverlay();$('#'+id)?.focus({preventScroll:true});updateCurrency();syncQuickState();save();}
});
document.addEventListener('keydown',event=>{if(event.target.id==='highlighted-matches'&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();if(event.key==='Home'||event.key==='End')event.target.scrollTo({left:event.key==='Home'?0:event.target.scrollWidth,behavior:motionEnabled()?'smooth':'instant'});else moveCarousel(event.key==='ArrowLeft'?-1:1);return;}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openOverlay('search');return;}if(event.target.matches('[data-bet-mode]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?'single':event.key==='End'?'quick':state.betMode==='quick'?'single':'quick';$('[data-bet-mode='+next+']')?.click();return;}if(event.key==='/'&&!$('#overlay').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){event.preventDefault();openOverlay('search');}});
$('#overlay').addEventListener('close',()=>{if(overlayKind==='cashout')state.pendingCashout=null;document.body.classList.remove('modal-open');syncShell();if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true});if(overlayKind==='slip')$('#overlay').innerHTML='';});
$('#overlay').addEventListener('click',event=>{if(event.target===$('#overlay')){const rect=event.target.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeOverlay();}});
desktopPanel.addEventListener('change',()=>{if(desktopPanel.matches&&$('#overlay').open&&overlayKind==='slip')closeOverlay();drawBetPanel();syncQuickState();});
document.addEventListener('toggle',event=>{if(event.target.matches('[data-nav-group]')){const key=event.target.dataset.navGroup;state.navClosed=event.target.open?state.navClosed.filter(name=>name!==key):[...new Set([...state.navClosed,key])];save();}if(event.target.open&&event.target.matches('details.activity'))reveal($('.activity-content',event.target));if(event.target.open&&event.target.matches('.panel-settings'))reveal($('.currency-controls',event.target));},true);
window.addEventListener('resize',syncShell,{passive:true});
window.addEventListener('hashchange',navigate);
shell();
